source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    # Objects are hollow pluses with 2s on their four orthogonal arms.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 2 and grid[r+1][c] == 2
                    and grid[r][c-1] == 2 and grid[r][c+1] == 2):
                centers.append((r, c))
    # In each row and column, join only consecutive plus centers.
    by_row = {}
    by_col = {}
    for r, c in centers:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    for r, cols in by_row.items():
        cols.sort()
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 2, b - 1):
                out[r][c] = 1
    for c, rows in by_col.items():
        rows.sort()
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 2, b - 1):
                out[r][c] = 1
    return out
